styl:
u + .body .gmail-blend-screen { background: #000;
  mix-blend-mode: screen; }
u + .body .gmail-blend-diff { background: #000;
  mix-blend-mode: difference; }
.bgr-image { background: url("https://fsms.quadcode.com/storage/public/d6/26/tn7vhhgea139ulh0/rfm-331-background.png") center no-repeat;
  background-size: cover;
  background-color: #000; }
.brad-full { border-radius: 32px !important; }
.w280 { width: 100%;
  max-width: 280px; }
@media screen and (max-width: 600px) {
  .w280 { max-width: 100% !important; }
}
.butt-link { font-size: 18px;
  line-height: 27px;
  font-weight: 700;
  text-transform: none;
  text-decoration: none;
  color: #f9f9f9;
  display: block;
  padding: 16px 0 16px;
  text-align: center;
  letter-spacing: 0px; }
.white-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 40px;
  line-height: 50px;
  color: #fff;
  word-break: break-word; }
@media screen and (max-width: 600px) {
  .white-title { font-size: 26px !important;
    line-height: 32px !important; }
}
.white-text { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 18px;
  line-height: 27px;
  color: #fff;
  padding-right: 20px; }
@media screen and (max-width: 600px) {
  .white-text { padding-right: 0 !important; }
}
.pb8 { padding-bottom: 8px; }
.pb16 { padding-bottom: 16px; }
.pb24 { padding-bottom: 24px; }
.h-24 { font-size: 8px;
  line-height: 24px;
  height: 24px; }
